// Number of index pairs with a[i] + a[j] <= k in the sorted array.
long long countAtMost(long long k) {
    long long left = 0, right = (long long)a.size() - 1, answer = 0;
    while (left < right) {
        if (a[left] + a[right] <= k) {
            answer += right - left;
            left++;
        } else {
            right--;
        }
    }
    return answer;
}

