import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    // Number of index pairs with a[i] + a[j] <= k in the sorted array.
    static long countAtMost(long[] a, long k) {
        int left = 0, right = a.length - 1;
        long answer = 0;
        while (left < right) {
            if (a[left] + a[right] <= k) {
                answer += right - left;
                left++;
            } else {
                right--;
            }
        }
        return answer;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long low = nextLong(), high = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        System.out.println(countAtMost(a, high) - countAtMost(a, low - 1));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

// Number of index pairs with a[i] + a[j] <= k in the sorted array.
func countAtMost(a []int64, k int64) int64 {
	left, right := 0, len(a)-1
	var answer int64
	for left < right {
		if a[left]+a[right] <= k {
			answer += int64(right - left)
			left++
		} else {
			right--
		}
	}
	return answer
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	low, high := nextInt(), nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	slices.Sort(a)
	fmt.Println(countAtMost(a, high) - countAtMost(a, low-1))
}
